import {backend} from './backend.js';
let stats=null,failed=false;
export async function trackVisit(){try{let id=localStorage.getItem('lexamah:visitor-id');if(!id){id=crypto.randomUUID();localStorage.setItem('lexamah:visitor-id',id);}await backend.trackVisit(id);}catch{/* Tracking does not block studying. */}}
export async function loadStats(){try{stats=await backend.adminStats();failed=false;}catch{failed=true;}}
export function statsCards(){if(failed)return '<div class="notice">Usage statistics need setup. Run supabase/launch-tools.sql, then refresh the Admin Dashboard.</div>';if(!stats)return '';const n=value=>Math.max(0,Number(value)||0).toLocaleString();return `<div class="section-title"><h2>Usage statistics</h2></div><div class="stats">${[[stats.visitors_7d,'Active browsers · 7 days','Browser identifiers; not unique people'],[stats.registered_users,'Registered accounts','LexAmah user profiles'],[stats.active_users_7d,'Active accounts · 7 days','Signed-in accounts'],[stats.downloads,'Downloads authorized','Since tracking was enabled']].map(([value,label,description])=>`<div class="stat"><div><small>${label}</small><strong>${n(value)}</strong><span class="sub">${description}</span></div></div>`).join('')}</div>`;}
